INSERT INTO `roles` VALUES (1,'super_admin','مدير المشروع','مدير منصة SmartSys، مسؤول إدارة المستأجرين والاشتراكات وإعدادات النظام وصلاحياته على مستوى المنصة.','2025-07-08 21:35:06','2026-11-26 20:40:35',NULL,1,NULL,0,'super_admin',10,1,NULL),(2,'admin','مدير المنشأة','يدير المحل أو الشركة (المنشأة)، ويشرف على موظفيها وأدوارهم وصلاحياتهم ونطاق الفروع المخصصة لهم.','2025-07-08 21:35:06','2026-11-26 20:40:35',NULL,1,NULL,0,'admin',20,1,NULL),(3,'manager','مشرف الفروع','يشرف على فرع واحد أو عدة فروع يخصصها له مدير المنشأة، وينفذ العمليات الإدارية ضمن صلاحياته ونطاق فروعه.','2025-07-08 21:35:06','2026-11-26 20:40:35',NULL,1,NULL,0,'manager',30,1,NULL),(4,'cashier','موظف المبيعات والمرتجعات','ينفذ عمليات البيع وتسجيل المدفوعات والمرتجعات المصرح بها، ويتعامل مع جلسات نقطة البيع ضمن صلاحياته.','2025-07-08 21:35:06','2026-11-26 20:40:35',NULL,1,NULL,0,'cashier',40,1,NULL),(5,'inventory_clerk','مسؤول المخزون','يتابع أرصدة وحركات المخزون، وينفذ التسويات والتحويلات وإجراءات المنتجات المصرح بها.','2025-07-08 21:35:06','2026-11-26 20:40:35',NULL,1,NULL,0,'inventory_clerk',50,1,NULL),(9,'finance_officer','المسؤول المالي','يتابع العمليات والتقارير والاعتمادات المالية التي يمنحها مدير المنشأة، ضمن نطاق المنشأة والفروع المخصصة له.','2025-09-02 11:00:09','2026-11-26 20:40:35',NULL,1,NULL,0,'finance_officer',60,1,NULL);

